INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (@tema_id, @seccion_id, 'epigrafe', '6.1', 'Recapitulación', '<p>El régimen del personal de las Cortes Generales se fundamenta en la autonomía parlamentaria del <span class="uji-ref" data-norma="CE" data-arts="72.1">art. 72.1 CE</span> y se regula, con carácter principal, por el Estatuto del Personal de las Cortes Generales de 2025.</p><p>Ese régimen configura una Administración parlamentaria propia, integrada fundamentalmente por personal funcionario especializado y organizada en siete Cuerpos profesionales. El acceso se rige por igualdad, mérito y capacidad; la carrera se articula mediante promoción interna, provisión de puestos y carrera horizontal; y el vínculo funcionarial se adapta a las circunstancias personales y profesionales a través de las distintas situaciones administrativas.</p><p>La especialización, estabilidad y neutralidad del personal parlamentario son garantías necesarias para la continuidad institucional, la autonomía de las Cámaras y el correcto ejercicio de las funciones constitucionales de las Cortes Generales.</p>', 1);

